(()=>{'use strict';
const normalize=s=>String(s||'').replace(/[\s\u200c]/g,'').replace(/ي/g,'ی').replace(/ك/g,'ک').toLowerCase();
studentTable=function(list){const groups=learnerGroups(list);return `<section class="learner-directory"><label class="directory-search">جست‌وجوی هنرجو<input class="portal-learner-search" type="search" placeholder="نام هنرجو، ساز، استاد یا شماره…" aria-label="جست‌وجوی هنرجویان این فهرست"></label><p class="directory-count" role="status">${money(groups.length)} هنرجو</p><div class="directory-items">${groups.map(courses=>{const s=courses[0];return `<article class="directory-person" data-search="${esc(normalize(courses.map(c=>full(c)+' '+classLabel(c)+' '+(c.mobile||'')).join(' ')))}"><div class="directory-person-head"><span class="directory-avatar" aria-hidden="true">${esc(s.first_name?.slice(0,1)||'♫')}</span><div><h3>${esc(full(s))}</h3><small>${money(courses.length)} کلاس${s.archived_at?' · بایگانی‌شده':''}</small></div></div><div class="directory-courses">${courses.map(c=>`<div class="directory-course"><div><strong>${esc(c.subject)}</strong><p>استاد ${esc(teacher(c.teacher_id))} · ${days[c.weekday]} · <bdi>${esc(c.class_time?.slice(0,5))}</bdi></p></div><button type="button" onclick="PracticeJournal.open('${esc(c.id)}')">${role==='teacher'||admin&&c.teacher_id===currentTeacherId?'امتیاز و تمرین':'دفتر پیشرفت'}</button></div>`).join('')}</div>${office?`<details><summary>پرونده و شهریه</summary>${courses.map(c=>classCard(c,true)).join('')}<button onclick="studentDetail('${esc(s.id)}')">اطلاعات پرونده</button></details>`:''}</article>`}).join('')||'<p class="empty">هنرجویی در این فهرست نیست.</p>'}</div><p class="directory-empty" hidden>نتیجه‌ای پیدا نشد.</p></section>`};
document.addEventListener('input',e=>{if(!e.target.matches('.portal-learner-search'))return;const root=e.target.closest('.learner-directory'),q=normalize(e.target.value);let count=0;for(const row of root.querySelectorAll('.directory-person')){row.hidden=!row.dataset.search.includes(q);if(!row.hidden)count++;}root.querySelector('.directory-count').textContent=money(count)+' هنرجو';root.querySelector('.directory-empty').hidden=count!==0;});
// Prevent scrolling the document beneath a modal; keep the modal's own scroller.
let locked=false,previous='';const sync=()=>{const open=!!document.querySelector('dialog[open]');if(open&&!locked){previous=document.documentElement.style.overflow;document.documentElement.style.overflow='hidden';locked=true;}else if(!open&&locked){document.documentElement.style.overflow=previous;locked=false;}};new MutationObserver(sync).observe(document.body,{subtree:true,attributes:true,attributeFilter:['open']});
if(uid)render();
})();
